function settleWithin<T>(promise:Promise<T>,fallback:T,timeoutMs=1800){return Promise.race([promise.catch(()=>fallback),new Promise<T>(resolve=>setTimeout(()=>resolve(fallback),timeoutMs))]);}
function omitCollectionArtwork(records:Game[]):Game[]{return records.map(game=>game.title==='Super Turrican Collection'?{...game,image:undefined,scene:undefined}:game);}
function libraryKey(game:Game){return `${game.system.toLocaleLowerCase()}::${game.title.toLocaleLowerCase()}`;}
function savedSynopsis(value?:string){const text=value?.trim();return text&&!text.startsWith('Found on your MiSTer')?text:undefined;}
function retainVisibleArtwork(previous:Game[],next:Game[]):Game[]{
 const existing=new Map(previous.map(game=>[libraryKey(game),game]));
 return next.map(game=>{const old=existing.get(libraryKey(game));return old?{...game,image:old.image,scene:old.scene,description:savedSynopsis(old.description)||game.description}:game;});
}function isPlayableGame(game:Game){const title=game.title.trim();const path=game.remoteFilePath??'';const compact=(title+' '+path).toLowerCase().replace(/[^a-z0-9]/g,'');if(compact.includes('240ptestsuite'))return false;if(/^boot(?:\d+)?(?:\.[a-z0-9]+)?$/i.test(title))return false;const value=`${title} ${path}`.toLowerCase();if(/(^|[\\/ _.-])(boot\d*|bios|readme|manual|license|240p|288p|test suite|tests?)([\\/ _.-]|$)/i.test(value))return false;if(/\.(?:txt|nfo|xml|cue|m3u|ini|cfg|pdf)$/i.test(path))return false;const isAmigaVision=game.remoteSystemId?.trim().toLowerCase()==='amiga'&&/\/games\/amiga\/(games|demos)\//i.test(path);if(isAmigaVision){if(/\/games\/amiga\/demos\//i.test(path))return false;const language=title.match(/\[([^\]]+)\]\s*$/)?.[1]??path.match(/\[([^\]]+)\]\s*$/)?.[1]??'';if(!/(^|[,+ _-])en($|[,+ _-])/i.test(language))return false;}return true;}
function tap() {if(Platform.OS!=='web')void Haptics.selectionAsync().catch(()=>{});}
function buildLibraryFacets(records:Game[]){const systems:{Arcade:string[];Consoles:string[];Computers:string[]}={Arcade:[],Consoles:[],Computers:[]};const systemSets={Arcade:new Set<string>(),Consoles:new Set<string>(),Computers:new Set<string>()};const genreSets=new Map<string,Set<string>>();for(const game of records){systemSets[game.category].add(game.system);for(const category of [game.category,'All'])for(const system of [game.system,'*']){const key=`${category}|${system}`;const set=genreSets.get(key)??new Set<string>();const genre=primaryGenre(game.genre);if(genre!=='Not listed')set.add(genre);genreSets.set(key,set);}}for(const category of ['Arcade','Consoles','Computers'] as const)systems[category]=[...systemSets[category]].sort((a,b)=>a.localeCompare(b));return {systems,genres:(category:Category,system:string|null)=>[...(genreSets.get(`${category}|${system??'*'}`)??[])].sort((a,b)=>a.localeCompare(b))};}
