   const changedIds=[...changedSystems];await importMiSTerGamelistMetadata(url,changedIds,()=>{});
   const refreshed=await readMiSTerLibraryWithMetadata(url,()=>{},changedIds);
   const changedKeys=new Set(changedIds.map(id=>id.toLocaleLowerCase()));
   setLibraryRecords(current=>{const combined=groupGenericArcadeGames([...current.filter(game=>!changedKeys.has(game.remoteSystemId?.toLocaleLowerCase()??'')),...retainVisibleArtwork(current,refreshed)]).sort((a,b)=>a.title.localeCompare(b.title));void saveCachedMiSTerLibrary(combined);return combined;});
   notify(`IGDB added ${saved} rating${saved===1?'':'s'} and refreshed ${changedIds.length} system${changedIds.length===1?'':'s'}.`);
