 async function batchLibretro(){if(!batchSystems.length||batchRunning)return;batchCancelled.current=false;setBatchCancelling(false);setBatchRunning(true);const total=playableGames.filter(game=>batchSystems.includes(game.system)).length;setBatchProgress({done:0,total});try{const result=await batchDownloadLibretro(playableGames,batchSystems,(done,totalItems)=>setBatchProgress({done,total:totalItems}),{isCancelled:()=>batchCancelled.current});const [stats,status]=await Promise.all([getLibretroArtworkStats(),getLibretroArtworkSystemStatus(playableGames)]);setArtworkCacheStats(stats);setBatchCacheStatus(status);notify(result.cancelled?`Artwork download stopped after ${result.checked.toLocaleString()} games.`:result.checked?`${result.available.toLocaleString()} of ${result.checked.toLocaleString()} games have artwork. ${result.skipped.toLocaleString()} were already complete; ${result.unmatched.toLocaleString()} had no Libretro match.`:'No games matched the selected system.');}finally{setBatchCancelling(false);setBatchRunning(false);}}
