function LibraryReadProgress({count}:{count:number}){const travel=useRef(new Animated.Value(0)).current;useEffect(()=>{const animation=Animated.loop(Animated.timing(travel,{toValue:1,duration:1200,useNativeDriver:true}));animation.start();return()=>animation.stop();},[travel]);return <View style={s.readProgress}><View style={s.readProgressTrack}><Animated.View style={[s.readProgressFill,{transform:[{translateX:travel.interpolate({inputRange:[0,1],outputRange:['-120%','260%']})}]}]}/></View><Text style={s.readProgressText}>{count?`${count.toLocaleString()} games read`:'Opening your library…'}</Text></View>;}
function SyncReadProgress({count,total}:{count:number;total:number}){const percent=total?Math.min(98,Math.max(4,Math.round(count/total*100))):8;return <View style={{marginVertical:16}}><View style={{height:7,borderRadius:4,overflow:'hidden',backgroundColor:'#D8CDB9'}}><View style={{height:'100%',width:`${percent}%`,borderRadius:4,backgroundColor:c.orange}}/></View><Text style={[s.readProgressText,{marginTop:8}]}>{count.toLocaleString()} of {total?`about ${total.toLocaleString()}`:'your'} records read</Text></View>;}
function SettingsSection({title,summary,open,onToggle,children}:{title:string;summary:string;open:boolean;onToggle:()=>void;children:React.ReactNode}){
 return <View style={{borderWidth:1,borderColor:'#D5C7AF',borderRadius:12,overflow:'hidden',backgroundColor:'rgba(255,249,237,.54)',marginBottom:10}}><Pressable onPress={()=>{tap();onToggle();}} accessibilityRole="button" accessibilityState={{expanded:open}} accessibilityLabel={`${open?'Collapse':'Expand'} ${title}`} style={({pressed})=>[{paddingHorizontal:14,paddingVertical:13,flexDirection:'row',alignItems:'center',gap:10},pressed&&{backgroundColor:'rgba(190,112,63,.12)',opacity:.86}]}><View style={{flex:1}}><Label>{title}</Label><Text numberOfLines={1} style={[s.sheetCopy,{marginTop:3,fontSize:11}]}>{summary}</Text></View><Text style={{fontFamily:fonts.medium,fontSize:21,color:c.orange,lineHeight:22}}>{open?'−':'+'}</Text></Pressable>{open&&<View style={{paddingHorizontal:14,paddingBottom:15,borderTopWidth:1,borderTopColor:'#E0D4C0'}}>{children}</View>}</View>;
}
type SystemFamily='Arcade'|'Consoles'|'Computers';
function systemFamily(system:MiSTerSystem):SystemFamily{const category=(system.category??'').toLocaleLowerCase();return category.includes('arcade')?'Arcade':category.includes('computer')?'Computers':'Consoles';}
function LibrarySystemPicker({systems,selection,onSelection,disabled,onLoad}:{systems:MiSTerSystem[];selection:string[];onSelection:(ids:string[])=>void;disabled:boolean;onLoad:()=>void}){
 const [open,setOpen]=useState<SystemFamily|null>(null);
 const groups=useMemo(()=>({Arcade:systems.filter(system=>systemFamily(system)==='Arcade'),Consoles:systems.filter(system=>systemFamily(system)==='Consoles'),Computers:systems.filter(system=>systemFamily(system)==='Computers')}),[systems]);
 const toggle=(id:string)=>onSelection(selection.includes(id)?selection.filter(value=>value!==id):[...selection,id]);
 const selectGroup=(items:MiSTerSystem[])=>onSelection(items.map(item=>item.id));
 const isExactlySelected=(items:MiSTerSystem[])=>items.length>0&&items.length===selection.length&&items.every(item=>selection.includes(item.id));
 const selectorStyle=[s.sortOption,{backgroundColor:'#E8DCC7',borderWidth:1,borderColor:'#C8B798',borderRadius:8,paddingHorizontal:12}] as const;
 return <View style={{gap:5,marginTop:10}}>
  <Text style={s.sheetCopy}>{selection.length?`${selection.length} systems selected for both actions below.`:'Choose a group, or open the lists to choose platforms.'}</Text>
  {(['Arcade','Consoles','Computers'] as SystemFamily[]).map(family=>{const items=groups[family];const selected=items.filter(item=>selection.includes(item.id)).length;const expanded=open===family;const allSelected=isExactlySelected(items);return <View key={family}><Pressable disabled={disabled} onPress={()=>{if(!systems.length)onLoad();setOpen(expanded?null:family);}} accessibilityRole="button" accessibilityState={{expanded}} accessibilityLabel={`${expanded?'Hide':'Choose'} ${family} systems`} style={[...selectorStyle,disabled&&{opacity:.45}]}><Text style={s.body}>{family}<Text style={{color:c.muted}}>  ·  {selected?`${selected} selected`:items.length?`${items.length} platforms`:'Loading…'}</Text></Text><Text style={[s.orangeText,{fontSize:15}]}>{expanded?'⌃':'⌄'}</Text></Pressable>{expanded&&<View style={{backgroundColor:'#F9F1E3',borderWidth:1,borderColor:'#C8B798',borderRadius:8,marginTop:3,maxHeight:280}}><ScrollView nestedScrollEnabled keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator><Pressable onPress={()=>selectGroup(items)} style={[s.sortOption,allSelected&&{backgroundColor:'rgba(190,112,63,.10)'}]} accessibilityRole="checkbox" accessibilityState={{checked:allSelected}}><Text style={s.body}>All {family}</Text><Text style={[s.orangeText,{fontSize:11}]}>{allSelected?'Selected':''}</Text></Pressable>{items.map(system=>{const isSelected=selection.includes(system.id);return <Pressable key={system.id} onPress={()=>toggle(system.id)} style={[s.sortOption,isSelected&&{backgroundColor:'rgba(190,112,63,.10)'}]} accessibilityRole="checkbox" accessibilityState={{checked:isSelected}}><Text style={s.body}>{system.name}<Text style={{color:c.muted}}>  ·  {(system.mediaCount??0).toLocaleString()} records</Text></Text><Text style={[s.orangeText,{fontSize:11}]}>{isSelected?'Selected':''}</Text></Pressable>;})}{!items.length&&<Text style={[s.sheetCopy,{padding:12}]}>Loading systems from Zaparoo…</Text>}</ScrollView></View>}</View>;})}
 </View>;
}
